"""Standalone Blender 4.2+ mechanical globe builder. No third-party Python modules.

Run in Blender, not system Python:
  blender --background --factory-startup --python build_mechanical_globe.py -- --output ./Export

Creates a separate collection; never deletes objects from the open Blender scene.
Textures are real PNG files, not unbaked procedural shader dependencies.
The FBX must be inspected in Unity before replacing any existing scene visuals.
"""
import argparse
import base64
from array import array
import json
import math
from pathlib import Path
import struct
import sys
import zlib

import bpy
import bmesh
from mathutils import Matrix, Vector
from mathutils.geometry import tessellate_polygon

# Public-domain Natural Earth 1:110m land polygons, embedded for offline use.
EMBEDDED_LAND = ""
SOURCE_URL = "https://github.com/nvkelso/natural-earth-vector/blob/master/geojson/ne_110m_land.geojson"
TAU = math.tau
SPHERE_CENTER = (-1.45, 2.15, -0.33)
ROOT_POSITION_UNITY = (0.13400006294250489, 0.06879997253417969, 0.023600000888109208)
ROOT_SCALE_UNITY = (0.9200000166893005,) * 3
EXPECTED_MIN = (-2.13, 0.86, -1.01)
EXPECTED_MAX = (-0.33, 2.927, 0.35)
OBJECTS = []


def u(v):
    """Unity parent-local X/right, Y/up, Z/away -> Blender X/right, Y/away, Z/up (handedness converted)."""
    return Vector((v[0], v[2], v[1]))


def unity_rotation(axis, degrees):
    basis = Matrix(((1, 0, 0), (0, 0, 1), (0, 1, 0)))
    return (basis @ Matrix.Rotation(math.radians(degrees), 3, axis) @ basis.inverted()).to_quaternion()


def png(path, width, height, pixels):
    def chunk(kind, data):
        return struct.pack('>I', len(data)) + kind + data + struct.pack('>I', zlib.crc32(kind + data) & 0xffffffff)
    stride = width * 4
    raw = b''.join(b'\0' + bytes(pixels[y * stride:(y + 1) * stride]) for y in range(height))
    path.write_bytes(b'\x89PNG\r\n\x1a\n' + chunk(b'IHDR', struct.pack('>IIBBBBB', width, height, 8, 6, 0, 0, 0))
                     + chunk(b'IDAT', zlib.compress(raw, 7)) + chunk(b'IEND', b''))


def polygons():
    data = json.loads(zlib.decompress(base64.b64decode(EMBEDDED_LAND)))
    result = []
    for feature in data['features']:
        geometry = feature['geometry']
        result.extend(geometry['coordinates'] if geometry['type'] == 'MultiPolygon' else [geometry['coordinates']])
    return result


def raster_land(polys, width, height):
    mask = bytearray(width * height)
    for poly in polys:
        rings = [[((lon + 180) / 360 * width, (90 - lat) / 180 * height) for lon, lat, *_ in ring] for ring in poly]
        low = max(0, int(min(p[1] for ring in rings for p in ring)))
        high = min(height - 1, int(max(p[1] for ring in rings for p in ring)) + 1)
        edges = [(ring[i - 1], ring[i]) for ring in rings for i in range(len(ring))]
        for y in range(low, high + 1):
            scan = y + .5
            xs = sorted(a[0] + (scan - a[1]) * (b[0] - a[0]) / (b[1] - a[1])
                        for a, b in edges if (a[1] > scan) != (b[1] > scan))
            for i in range(0, len(xs) - 1, 2):
                start, end = max(0, math.ceil(xs[i] - .5)), min(width, math.ceil(xs[i + 1] - .5))
                mask[y * width + start:y * width + end] = b'\xff' * max(0, end - start)
    return mask


def byte(value):
    return max(0, min(255, round(value)))


FONT = {
    '0': ('111', '101', '101', '101', '111'), '1': ('010', '110', '010', '010', '111'),
    '2': ('111', '001', '111', '100', '111'), '3': ('111', '001', '111', '001', '111'),
    '4': ('101', '101', '111', '001', '001'), '5': ('111', '100', '111', '001', '111'),
    'R': ('110', '101', '110', '101', '101'), 'P': ('110', '101', '110', '100', '100'),
    'M': ('101', '111', '111', '101', '101'),
}


def generate_textures(out, polys, width):
    height = width // 2
    mask = raster_land(polys, width, height)
    configs = {
        'DarkShell': ((31, 43, 46), .78, .36), 'AntiqueBrass': ((148, 103, 45), .86, .42),
        'EngravedLand': ((124, 116, 78), .70, .46), 'AmberAccent': ((181, 85, 18), .35, .34),
        'GaugeFace': ((220, 207, 170), 0, .70), 'GaugeNeedle': ((159, 28, 12), .20, .38),
    }
    sets = {}
    for name, (base, metallic, roughness) in configs.items():
        w, h = (width, height) if name == 'DarkShell' else (512, 512)
        albedo, packed, normal = bytearray(w*h*4), bytearray(w*h*4), bytearray(w*h*4)
        heights = array('f', [0]) * (w*h)
        for y in range(h):
            for x in range(w):
                k = y*w+x; q = k*4
                cloud = math.sin(x*.029 + math.sin(y*.017)) * math.sin(y*.041)
                grain = math.sin(x*1.17+y*.019) * .7 + math.sin(y*2.13) * .3
                tarnish = max(0, cloud) * .09 if name == 'AntiqueBrass' else 0
                variation = .012*grain - tarnish
                coast = False
                if name == 'DarkShell':
                    coast = any(mask[k] != mask[max(0, min(h-1, y+dy))*w+(x+dx)%w]
                                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)))
                    variation -= .22 if coast else 0
                    if x % max(1, w//12) == 0 or y % max(1, h//6) == 0: variation += .13
                for c in range(3): albedo[q+c] = byte(base[c]*(1+variation))
                albedo[q+3] = 255
                packed[q:q+4] = bytes((byte(metallic*(1-tarnish)*255), 0, 0, byte((1-roughness-tarnish)*255)))
                heights[k] = .03*grain - (.25 if coast else 0)
        for y in range(h):
            for x in range(w):
                q=(y*w+x)*4
                dx=(heights[y*w+(x+1)%w]-heights[y*w+(x-1)%w])*.3
                dy=(heights[max(0,y-1)*w+x]-heights[min(h-1,y+1)*w+x])*.3
                length=math.sqrt(dx*dx+dy*dy+1)
                normal[q:q+4]=bytes((byte((-dx/length*.5+.5)*255),byte((-dy/length*.5+.5)*255),byte((1/length*.5+.5)*255),255))
        if name == 'GaugeFace':
            def dot(x, y, radius=2):
                for yy in range(max(0, y-radius), min(h, y+radius+1)):
                    for xx in range(max(0, x-radius), min(w, x+radius+1)):
                        i=(yy*w+xx)*4; albedo[i:i+3]=bytes((26,29,28))
            def text(label, cx, cy, scale=8):
                start=cx-(len(label)*4-1)*scale//2
                for index, char in enumerate(label):
                    for yy,row in enumerate(FONT[char]):
                        for xx,on in enumerate(row):
                            if on=='1':
                                for sy in range(scale):
                                    for sx in range(scale):dot(start+(index*4+xx)*scale+sx,cy+yy*scale+sy,0)
            for i in range(51):
                a=math.radians(225-i*270/50)
                for radius in range(182 if i%10==0 else 204,224):
                    dot(round(w/2+math.cos(a)*radius),round(h/2-math.sin(a)*radius),2 if i%10==0 else 1)
            for i in range(6):
                a=math.radians(225-i*54);text(str(i),round(w/2+math.cos(a)*155),round(h/2-math.sin(a)*155)-20,7)
            text('RPM',w//2,333,7)
        files={}
        for suffix, data in [('BaseColor',albedo),('Normal',normal),('MetallicSmoothness',packed)]:
            path=out/(name+'_'+suffix+'.png');png(path,w,h,data);files[suffix]=path
        sets[name]=files
    return sets, mask, width, height


def make_material(name, textures):
    mat=bpy.data.materials.new(name);mat.use_nodes=True
    nodes=mat.node_tree.nodes;links=mat.node_tree.links;bsdf=nodes.get('Principled BSDF')
    images={}
    for key,path in textures.items():
        image=bpy.data.images.load(str(path),check_existing=True)
        image.colorspace_settings.name='sRGB' if key=='BaseColor' else 'Non-Color'
        node=nodes.new('ShaderNodeTexImage');node.image=image;node.label=key;images[key]=node
    links.new(images['BaseColor'].outputs['Color'],bsdf.inputs['Base Color'])
    split=nodes.new('ShaderNodeSeparateColor');links.new(images['MetallicSmoothness'].outputs['Color'],split.inputs[0])
    links.new(split.outputs[0],bsdf.inputs['Metallic'])
    invert=nodes.new('ShaderNodeMath');invert.operation='SUBTRACT';invert.inputs[0].default_value=1
    links.new(images['MetallicSmoothness'].outputs['Alpha'],invert.inputs[1]);links.new(invert.outputs[0],bsdf.inputs['Roughness'])
    normal=nodes.new('ShaderNodeNormalMap');normal.inputs['Strength'].default_value=.30
    links.new(images['Normal'].outputs['Color'],normal.inputs['Color']);links.new(normal.outputs['Normal'],bsdf.inputs['Normal'])
    if name in ('AmberAccent','GaugeFace'):
        emission='Emission Color' if 'Emission Color' in bsdf.inputs else 'Emission'
        links.new(images['BaseColor'].outputs['Color'],bsdf.inputs[emission]);bsdf.inputs['Emission Strength'].default_value=.9 if name=='AmberAccent' else .35
    return mat


def empty(name, parent=None, position=(0,0,0)):
    obj=bpy.data.objects.new(name,None);COLLECTION.objects.link(obj);OBJECTS.append(obj);obj.parent=parent;obj.location=u(position);return obj


def mesh(name, verts, faces, parent, material, position=(0,0,0), uv=None, smooth=True):
    data=bpy.data.meshes.new(name+'_Mesh');data.from_pydata([tuple(u(v)) for v in verts],[],[tuple(reversed(face)) for face in faces]);data.update()
    obj=bpy.data.objects.new(name,data);COLLECTION.objects.link(obj);OBJECTS.append(obj);obj.parent=parent;obj.location=u(position);data.materials.append(material)
    for polygon in data.polygons:polygon.use_smooth=smooth
    if uv is None:
        uv=[(vertex[0]*4,vertex[1]*4) for vertex in verts]
    layer=data.uv_layers.new(name='UVMap')
    for loop in data.loops:layer.data[loop.index].uv=uv[loop.vertex_index]
    return obj


def torus(name, parent, radius, tube, material, position=(0,0,0), tilt_y=0, n=96, sides=10):
    verts=[];uv=[];faces=[]
    for i in range(n):
        a=i*TAU/n
        for j in range(sides):
            b=j*TAU/sides;verts.append(((radius+tube*math.cos(b))*math.cos(a),(radius+tube*math.cos(b))*math.sin(a),tube*math.sin(b)));uv.append((i/n,j/sides))
            k=i*sides+j;next_i=((i+1)%n)*sides+j;next_b=((i+1)%n)*sides+(j+1)%sides;last=i*sides+(j+1)%sides
            faces.append((k,next_i,next_b,last))
    obj=mesh(name,verts,faces,parent,material,position,uv);obj.rotation_mode='QUATERNION';obj.rotation_quaternion=unity_rotation('Y',tilt_y);return obj


def lathe(name,parent,profile,material,position=(0,0,0),segments=96):
    verts=[];uv=[];faces=[]
    for j,(radius,height) in enumerate(profile):
        for i in range(segments):
            a=i*TAU/segments;verts.append((radius*math.cos(a),height,radius*math.sin(a)));uv.append((i/segments,j/(len(profile)-1)))
            if j:
                k=j*segments+i;p=j*segments+(i+1)%segments;faces.append((k,p,p-segments,k-segments))
    verts.extend([(0,profile[0][1],0),(0,profile[-1][1],0)]);uv.extend([(0,0),(1,1)])
    for i in range(segments):
        faces.append((len(verts)-2,i,(i+1)%segments));offset=(len(profile)-1)*segments
        faces.append((len(verts)-1,offset+(i+1)%segments,offset+i))
    return mesh(name,verts,faces,parent,material,position,uv)


def gear(name,parent,position,radius,teeth,material,phase=0):
    pivot=empty(name+'_Pivot',parent,position);verts=[];faces=[];n=teeth*4;depth=.025
    for i in range(n):
        a=i*TAU/n+phase;outer=radius*(1 if i%4 in (1,2) else .84)
        for z in (-depth/2,depth/2):
            for r in (outer,radius*.43):verts.append((math.cos(a)*r,math.sin(a)*r,z))
    for i in range(n):
        a=i*4;b=((i+1)%n)*4
        faces.extend([(a,b,b+1,a+1),(a+2,a+3,b+3,b+2),(a,a+2,b+2,b),(a+1,b+1,b+3,a+3)])
    obj=mesh(name+'_ToothedWheel',verts,[tuple(reversed(face)) for face in faces],pivot,material,smooth=False)
    bevel=obj.modifiers.new('Machined tooth bevel','BEVEL');bevel.width=.0009;bevel.segments=2
    # Spokes are part of each gear pivot, not independent animation channels.
    for i in range(2):
        a=i*math.pi/2;length=radius*1.25;width=.012
        coords=[(-length/2,-width/2,-.010),(length/2,-width/2,-.010),(length/2,width/2,-.010),(-length/2,width/2,-.010),(-length/2,-width/2,.010),(length/2,-width/2,.010),(length/2,width/2,.010),(-length/2,width/2,.010)]
        coords=[(x*math.cos(a)-y*math.sin(a),x*math.sin(a)+y*math.cos(a),z) for x,y,z in coords]
        mesh(name+'_Spoke_'+str(i),coords,[(0,3,2,1),(4,5,6,7),(0,1,5,4),(1,2,6,5),(2,3,7,6),(3,0,4,7)],pivot,material,smooth=False)
    torus(name+'_AmberHub',pivot,.023,.0035,MATERIALS['AmberAccent'],(0,0,-.019),n=40,sides=8)
    return pivot


def spherical(lon,lat,radius):
    lon,lat=math.radians(lon),math.radians(lat)
    return (radius*math.cos(lat)*math.sin(lon),radius*math.sin(lat),-radius*math.cos(lat)*math.cos(lon))


def sphere_surface(parent,mask,width,height,segments):
    rings=segments//2;verts=[];uv=[];faces=[]
    for j in range(rings+1):
        lat=-90+j*180/rings
        for i in range(segments+1):
            lon=-180+i*360/segments
            x=min(width-1,int((lon+180)/360*width));y=min(height-1,max(0,int((90-lat)/180*height)))
            # Keep physical separation beneath the engraved geographic plates.
            radius=.6787
            verts.append(spherical(lon,lat,radius));uv.append((i/segments,j/rings))
            if j and i:
                k=j*(segments+1)+i
                if j==1:faces.append((k-1,k,k-(segments+1)))
                elif j==rings:faces.append((k-1,k-(segments+1),k-(segments+1)-1))
                else:faces.append((k-1,k,k-(segments+1),k-(segments+1)-1))
    return mesh('Sphere_DarkMetalShell',verts,faces,parent,MATERIALS['DarkShell'],uv=uv)


def engraved_land(parent,polys):
    verts=[];uv=[];faces=[]
    def triangle(a,b,c,depth=0):
        index=len(verts)
        for pt in (a,b,c):
            verts.append(spherical(pt.x,pt.y,.6788));uv.append(((pt.x+180)/360,(pt.y+90)/180))
        faces.append((index,index+1,index+2))
    parts=[]
    # Batch coastlines into eight replaceable mesh sections; keep geographic vertices.
    for batch in range(8):
        verts.clear();uv.clear();faces.clear()
        for poly in polys[batch::8]:
            outer=poly[0][:-1]
            if len(outer)<3:continue
            ring=[Vector((p[0],p[1],0)) for p in outer]
            for tri in tessellate_polygon([ring]):
                triangle(*(ring[index] for index in tri)) if isinstance(tri[0],int) else triangle(*tri)
        if not verts:continue
        outward=[]
        for face in faces:
            a,b,c=(Vector(verts[index]) for index in face)
            outward.append(tuple(reversed(face)) if (b-a).cross(c-a).dot(a+b+c)<0 else face)
        obj=mesh('Sphere_EngravedContinentSections_'+str(batch),verts.copy(),outward,parent,MATERIALS['EngravedLand'],uv=uv.copy())
        welded=bmesh.new();welded.from_mesh(obj.data)
        bmesh.ops.remove_doubles(welded,verts=list(welded.verts),dist=.000001)
        welded.to_mesh(obj.data);welded.free();obj.data.update()
        decimate=obj.modifiers.new('Preserve geographic boundary topology','DECIMATE');decimate.ratio=1.0
        # Tiny inward thickness keeps topographic plates distinct, with a visible recessed shoreline seat.
        solid=obj.modifiers.new('Inset continent plate thickness','SOLIDIFY');solid.thickness=.0006;solid.offset=-1
        parts.append(obj)
    return parts




def build(polys,mask,width,height,segments):
    root=empty('BlenderMechanicalGlobe_Visuals')
    sphere=empty('Sphere_RotationPivot',root,SPHERE_CENTER)
    sphere_surface(sphere,mask,width,height,segments);engraved_land(sphere,polys)
    meridian=empty('Meridian_Assembly',root,SPHERE_CENTER)
    torus('Meridian_AntiqueBrass_Outer',meridian,.760,.017,MATERIALS['AntiqueBrass'],tilt_y=30)
    torus('Meridian_AntiqueBrass_Inlay',meridian,.739,.004,MATERIALS['AntiqueBrass'],tilt_y=30)
    # Graduation marks share the meridian pivot and remain separate from the rotating sphere.
    for i in range(36):
        a=i*TAU/36;rot=Matrix.Rotation(math.radians(30),3,'Y')
        p=rot@Vector((math.cos(a)*.759,math.sin(a)*.759,0))
        tick=torus('Meridian_Graduation_'+str(i),meridian,.005 if i%3 else .008,.0015,MATERIALS['DarkShell'],tuple(p),tilt_y=30,n=12,sides=6)
    pedestal=empty('Pedestal_Assembly',root,(-1.45,.86,-.33))
    profile=[(.190,0),(.215,.018),(.215,.055),(.195,.075),(.195,.090),(.175,.11),(.175,.15),(.15,.18),(.12,.205),(.095,.24),(.074,.28),(.06,.34),(.055,.42),(.07,.47),(.095,.505),(.10,.53),(.09,.555),(.06,.585),(.045,.62),(.045,.74)]
    lathe('Pedestal_TurnedBrass',pedestal,profile,MATERIALS['AntiqueBrass'])
    for index,(radius,y) in enumerate(((.195,.07),(.174,.14),(.095,.52))):
        ring=torus('Pedestal_EngravedBand_'+str(index),pedestal,radius,.003,MATERIALS['DarkShell'],(0,y,0),n=64)
        ring.rotation_quaternion=unity_rotation('X',90)
    amber=torus('Pedestal_AmberInlay',pedestal,.096,.0035,MATERIALS['AmberAccent'],(0,.52,0),n=64)
    amber.rotation_quaternion=unity_rotation('X',90)
    clockwork=empty('Clockwork_Assembly',root)
    gear_specs=[('Gear_12T',(-1.72,1.68,-.935),.13,12,-1.6),('Gear_16T',(-1.45,1.57,-.94),.16,16,1.2),('Gear_14T',(-1.17,1.69,-.935),.14,14,-1.37142857)]
    for index,(name,position,radius,teeth,ratio) in enumerate(gear_specs):
        front=gear(name,clockwork,position,radius,teeth,MATERIALS['AntiqueBrass'],index*math.pi/teeth)
        front['unity_gear_ratio']=ratio
        back=gear(name+'_RearLayer',clockwork,(position[0],position[1],position[2]+.032),radius*.78,teeth,MATERIALS['DarkShell'],math.pi/teeth)
        # Rear wheel follows the same parent/pivot; animation has exactly three gear channels.
        back.parent=front;back.location=u((0,0,.032))
    gauge=empty('RPMGauge_Assembly',root,(-.49,1.43,-.75))
    housing=lathe('RPMGauge_DarkHousing',gauge,[(.154,-.065),(.16,-.055),(.16,.05),(.15,.065)],MATERIALS['DarkShell'])
    housing.rotation_mode='QUATERNION';housing.rotation_quaternion=unity_rotation('X',90)
    torus('RPMGauge_BrassBezel',gauge,.149,.011,MATERIALS['AntiqueBrass'],(0,0,-.075),n=80)
    verts=[(0,0,-.081)]+[(math.cos(i*TAU/80)*.141,math.sin(i*TAU/80)*.141,-.081) for i in range(80)]
    faces=[(0,(i+1)%80+1,i+1) for i in range(80)]
    uv=[(.5,.5)]+[(.5+math.cos(i*TAU/80)*.5,.5+math.sin(i*TAU/80)*.5) for i in range(80)]
    mesh('RPMGauge_PrintedDial',verts,faces,gauge,MATERIALS['GaugeFace'],uv=uv)
    needle=empty('RPMGauge_NeedlePivot',gauge,(0,0,-.094));needle.rotation_mode='QUATERNION';needle.rotation_quaternion=unity_rotation('Z',72)
    mesh('RPMGauge_AnalogNeedle',[(-.004,-.012,0),(.004,-.012,0),(.002,.112,0),(-.002,.112,0)],[(0,3,2,1)],needle,MATERIALS['GaugeNeedle'],smooth=False)
    torus('RPMGauge_NeedleHub',gauge,.008,.003,MATERIALS['AntiqueBrass'],(0,0,-.100),n=32)
    root['unity_root_position_do_not_apply_to_visual_child']=list(ROOT_POSITION_UNITY)
    root['unity_root_scale_do_not_apply_to_visual_child']=list(ROOT_SCALE_UNITY)
    return root,gear_specs


def main():
    args=argparse.ArgumentParser();args.add_argument('--output',default=str(Path(__file__).resolve().parent/'Export'));args.add_argument('--segments',type=int,default=192);args.add_argument('--texture-size',type=int,default=1024)
    argv=sys.argv[sys.argv.index('--')+1:] if '--' in sys.argv else [];options=args.parse_args(argv)
    if options.segments<48 or options.segments%2 or options.texture_size<256:raise ValueError('Use an even --segments >= 48 and --texture-size >= 256')
    output=Path(options.output).resolve();textures=output/'Textures';textures.mkdir(parents=True,exist_ok=True)
    global COLLECTION,MATERIALS
    COLLECTION=bpy.data.collections.new('DetectiveGlobe_Export');bpy.context.scene.collection.children.link(COLLECTION)
    bpy.context.scene.unit_settings.system='METRIC';bpy.context.scene.unit_settings.scale_length=1
    land=polygons();sets,mask,w,h=generate_textures(textures,land,options.texture_size)
    MATERIALS={name:make_material(name,paths) for name,paths in sets.items()}
    root,gear_specs=build(land,mask,w,h,options.segments)
    bpy.context.view_layer.update()
    # Apply visual modifiers only to exported mesh objects; preserve all animation origins.
    for obj in OBJECTS:
        if obj.type!='MESH':continue
        bpy.context.view_layer.objects.active=obj
        for modifier in list(obj.modifiers):
            was_decimate=modifier.type=='DECIMATE'
            bpy.ops.object.modifier_apply(modifier=modifier.name)
            if was_decimate and obj.name.startswith('Sphere_EngravedContinentSections'):
                bm=bmesh.new();bm.from_mesh(obj.data)
                bmesh.ops.triangulate(bm,faces=list(bm.faces))
                for vertex in bm.verts:vertex.co=vertex.co.normalized()*.6800
                for iteration in range(9):
                    edges=[edge for edge in bm.edges if edge.calc_length()>.045]
                    if not edges:break
                    bmesh.ops.subdivide_edges(bm,edges=edges,cuts=1,use_grid_fill=True)
                    for vertex in bm.verts:vertex.co=vertex.co.normalized()*.6800
                bmesh.ops.recalc_face_normals(bm,faces=list(bm.faces));bm.to_mesh(obj.data);bm.free();obj.data.update()
        triangulate=obj.modifiers.new('Unity triangles','TRIANGULATE');bpy.ops.object.modifier_apply(modifier=triangulate.name)
        if obj.name.startswith('Sphere_EngravedContinentSections'):
            for polygon in obj.data.polygons:polygon.use_smooth=True
            obj.data.normals_split_custom_set_from_vertices([vertex.co.normalized() for vertex in obj.data.vertices])
    bpy.ops.object.select_all(action='DESELECT')
    for obj in OBJECTS:obj.select_set(True)
    bpy.context.view_layer.objects.active=root
    triangles=sum(len(obj.data.polygons) for obj in OBJECTS if obj.type=='MESH')
    if not hasattr(bpy.ops.export_scene,'fbx'):raise RuntimeError('Blender FBX exporter unavailable. Enable the FBX import/export add-on and run again.')
    fbx=output/'MechanicalGlobe_Blender.fbx'
    bpy.ops.export_scene.fbx(filepath=str(fbx),use_selection=True,object_types={'MESH','EMPTY'},global_scale=1,apply_unit_scale=True,apply_scale_options='FBX_SCALE_UNITS',axis_forward='-Z',axis_up='Y',use_space_transform=True,bake_space_transform=False,use_mesh_modifiers=True,mesh_smooth_type='FACE',use_tspace=True,add_leaf_bones=False,bake_anim=False,path_mode='RELATIVE')
    bpy.ops.wm.save_as_mainfile(filepath=str(output/'MechanicalGlobe_Blender.blend'))
    manifest={'status':'BLENDER_EXPORT_COMPLETED_NOT_UNITY_VERIFIED','blender_version':bpy.app.version_string,'fbx':fbx.name,'triangles':triangles,'mesh_count':sum(obj.type=='MESH' for obj in OBJECTS),'units':'meters','authoring_axes':'Blender Z up; FBX -Z forward / Y up','expected_unity_parent_local_min':EXPECTED_MIN,'expected_unity_parent_local_max':EXPECTED_MAX,'retain_existing_unity_parent_position':ROOT_POSITION_UNITY,'retain_existing_unity_parent_scale':ROOT_SCALE_UNITY,'sphere_pivot_unity':SPHERE_CENTER,'gauge_pivot_unity':(-.49,1.43,-.75),'needle':'RPMGauge_NeedlePivot','gears':[{'pivot':name+'_Pivot','ratio':ratio} for name,_,_,_,ratio in gear_specs],'materials':{name:{key:'Textures/'+path.name for key,path in paths.items()} for name,paths in sets.items()},'geography_source':SOURCE_URL,'notes':['Do not trust automatic FBX Standard materials in URP; remap explicitly to URP/Lit.','Do not replace existing gameplay parent or RotatingSphere transform.','Geographic outlines use low-resolution Natural Earth coastlines, not survey-grade terrain.','Verify import axes, object origins, bounds, normals, and material maps before hiding original visuals.']}
    (output/'UnityImportManifest.json').write_text(json.dumps(manifest,indent=2),encoding='utf-8')
    print('BLENDER EXPORT COMPLETE:',fbx,'triangles:',triangles,'Unity verification still required.')


